CREATE QUEUE "many_requests" ( ID BIGINT NOT NULL , BATCH BIGINT NOT NULL , REJECT BIGINT NOT NULL ) WITH ( LEASE_DURATION = '120s' , MAX_LEASE_DURATION = '120s' );
CREATE TABLE "many_items" ( ID BIGINT PRIMARY KEY , BATCH BIGINT NOT NULL , NOTE TEXT );
CREATE STREAM "many_events" ( REQUEST BIGINT NOT NULL , ID BIGINT NOT NULL , NOTE TEXT );
CREATE STREAM "many_failures" ( REQUEST BIGINT NOT NULL , REASON TEXT NOT NULL );
CREATE DATAFLOW "many_route" FROM QUEUE "many_requests" AS "__t$1_request" AS BEGIN BEGIN ATOMIC LET "__t$2_selected" MANY ( 3 ) = SELECT ID , NOTE FROM "many_items" WHERE BATCH = "__t$1_request" . BATCH ORDER BY ID ; LET "__t$3_batch" = "__t$2_selected" ; FOR "__t$4_item" IN "__t$3_batch" DO LET "__t$5_entry" = "__t$4_item" ; LET "__t$6_entry" = "__t$5_entry" ; REQUIRE ( ( "__t$6_entry" ) . ID ) = "__t$6_entry" . ID ELSE 'InvalidItem' ; IF "__t$1_request" . REJECT = 1 THEN REQUIRE "__t$4_item" . ID <> 5 ELSE 'LateRefusal' ; END IF ; IF "__t$1_request" . REJECT = 2 THEN REQUIRE "__t$4_item" . ID <> 4 ELSE 'FirstKey' ; REQUIRE "__t$4_item" . ID <> 6 ELSE 'LastKey' ; END IF ; PRODUCE INTO "many_events" VALUES ( "__t$1_request" . ID , ( ( "__t$4_item" ) . ID ) , "__t$4_item" . NOTE ) ; END FOR ; END ; ON FAILURE "__t$7_failure" BEGIN ATOMIC PRODUCE INTO "many_failures" VALUES ( "__t$1_request" . ID , 'refused' ) ; END ; END;
AUTHORIZE DATAFLOW "many_route" AS ROLE CURRENT_ROLE;
ACTIVATE DATAFLOW "many_route";
CREATE QUEUE "other_requests" ( ID BIGINT NOT NULL , BATCH BIGINT NOT NULL , REJECT BIGINT NOT NULL ) WITH ( LEASE_DURATION = '120s' , MAX_LEASE_DURATION = '120s' );
CREATE TABLE "other_items" ( ID BIGINT PRIMARY KEY , BATCH BIGINT NOT NULL , NOTE TEXT );
CREATE STREAM "other_events" ( REQUEST BIGINT NOT NULL , ID BIGINT NOT NULL , NOTE TEXT );
CREATE STREAM "other_failures" ( REQUEST BIGINT NOT NULL , REASON TEXT NOT NULL );
CREATE DATAFLOW "other_route" FROM QUEUE "other_requests" AS "__t$1_request" AS BEGIN BEGIN ATOMIC LET "__t$2_selected" MANY ( 3 ) = SELECT ID , NOTE FROM "other_items" WHERE BATCH = "__t$1_request" . BATCH ORDER BY ID ; LET "__t$3_batch" = "__t$2_selected" ; FOR "__t$4_item" IN "__t$3_batch" DO LET "__t$5_entry" = "__t$4_item" ; LET "__t$6_entry" = "__t$5_entry" ; REQUIRE ( ( "__t$6_entry" ) . ID ) = "__t$6_entry" . ID ELSE 'InvalidItem' ; IF "__t$1_request" . REJECT = 1 THEN REQUIRE "__t$4_item" . ID <> 5 ELSE 'LateRefusal' ; END IF ; IF "__t$1_request" . REJECT = 2 THEN REQUIRE "__t$4_item" . ID <> 4 ELSE 'FirstKey' ; REQUIRE "__t$4_item" . ID <> 6 ELSE 'LastKey' ; END IF ; PRODUCE INTO "other_events" VALUES ( "__t$1_request" . ID , ( ( "__t$4_item" ) . ID ) , "__t$4_item" . NOTE ) ; END FOR ; END ; ON FAILURE "__t$7_failure" BEGIN ATOMIC PRODUCE INTO "other_failures" VALUES ( "__t$1_request" . ID , 'refused' ) ; END ; END;
AUTHORIZE DATAFLOW "other_route" AS ROLE CURRENT_ROLE;
ACTIVATE DATAFLOW "other_route";
